        function _composeBoutonsDroite() {
            return ['<div class="objetBandeauEntete_boutons">', (this.avecMenuSupp() ? this.composeMenuSupp() : ''), this.avecCloudIndex() ? '<span>' + '<ie-btnimage ie-model="btnDroite(' + this.getCommande(this.genreCommande.cloudIndex) + ')" class="icon_cloud_fossnote btnImageIcon" title="' + GTraductions.getValeur('cloudIndex.utilisationCloud') + '">' + '</ie-btnimage></span>' : '', this.composeBtnCommunication(this.NomBtnCommunication), this.composeCreationAlertePPMS ? this.composeCreationAlertePPMS() : '', this.composeConversation ? this.composeConversation() : '', this.GetInstance(this.identBoutonNotif) || this.composeAlertePPMS ? '<hr class="objetBandeauEntete_sep_boutons"></hr>' : '', this.GetInstance(this.identBoutonNotif) ? '<div id="' + this.GetInstance(this.identBoutonNotif).Nom + '" class="objetBandeauEntete_boutons_ifc"></div>' : '', this.GetInstance(this.identBoutonAide) ? '<div id="' + this.GetInstance(this.identBoutonAide).Nom + '" class="objetBandeauEntete_boutons_ifc"></div>' : '', this.composeAlertePPMS ? this.composeAlertePPMS() : '', '</div>'].join('');
        }

        function _composeMembre(aParams) {
            const lUrl = this.getUrlPhotoMembre ? this.getUrlPhotoMembre(aParams.membre) : null;
            if (lUrl === '') {
                return aParams.libelle;
            }
            if (lUrl && aParams.ajoutControleur && aParams.membreSource) {
                aParams.membre.controleur = {
                    node: function() {
                        $(this.node).on('error', function() {
                            aParams.membreSource._erreurChargementPhoto_ = true;
                        });
                    }
                };
            }
            const H = [];
            H.push('<div class="membre-photo_container">', '<div class="membre-photo">');
            if (lUrl && (!aParams.membreSource || !aParams.membreSource._erreurChargementPhoto_)) {
                H.push(tag('img', {
                    src: lUrl,
                    style: 'width:100%;',
                    'ie-node': (aParams.ajoutControleur && aParams.membreSource ? 'node' : ''),
                    onerror: `$(this).next('div').show();$(this).remove();`,
                    alt: GTraductions.getValeur('PhotoDe_S', [aParams.libelle])
                }));
            }
            H.push('<div style="', (!lUrl || (aParams.membreSource && aParams.membreSource._erreurChargementPhoto_) ? '' : 'display:none;'), '">', '<i class="icon_utilisateur"></i>', '</div>', '</div>');
            H.push('<span class="label-membre ie-ellipsis">', aParams.libelle, '</span>');
            if (aParams.avecObjetsGraphiqueMembre) {
                H.push(this.composeObjetsGraphiqueMembre(aParams.membre));
            }
            H.push('</div>');
            return H.join('');
        }

