                    lHtml.push('<div id="', this.idWrapperGlobal, '" style="position:absolute;top:20px;right:150px;bottom:20px;left:0px;text-align:right;">');
                    lHtml.push('<div class="InlineBlock" style="height:100%;vertical-align:middle;"></div>');
