                lHtml.push('<div style="position:absolute;top:0;left:0;width:100%;height:100%;"><table id="', this.idWrapperNavigation, this.indiceQuestion, '" style="width:100%;height:100%;"><tr>');
                lHtml.push('<td style="vertical-align:middle;">');
                lHtml.push('<div style="width:38px;height:30px;">&nbsp;</div>');
                lHtml.push('</td>');
