                lHtml.push('<div id="', this.idWrapperGlobal, '" style="position:absolute;top:20px;right:20px;bottom:20px;left:20px;">');
                lHtml.push('<div class="InlineBlock" style="height:100%;vertical-align:middle;"></div>');
                lHtml.push('<div class="InlineBlock" style="width:99%;color:#000;font-size:20px;text-align:left;vertical-align:middle;">');
