                lHtml.push('<div class="InlineBlock" style="height:100%;vertical-align:middle;"></div>');
                lHtml.push('<div class="InlineBlock" style="width:70%;background-color:#fff;color:#000;box-shadow: 0 3px 10px -5px #000000;font-size:20px;padding:10px 10px 30px 10px;text-align:left;vertical-align:middle;">');
                const lPossedeCopieCacheeDejaJouee = !!this.executionQCM.dateExecCopieCachee;
                if (this._estUnIDevoir(this.executionQCM) && lPossedeCopieCacheeDejaJouee) {
                    const lStrTypeQCMGarde = ['<span style="font-weight: bold;">'];
                    if (!!this.executionQCM.garderMeilleureNote) {
                        lStrTypeQCMGarde.push(GTraductions.getValeur('ExecutionQCM.presentationCorrige.MeilleurResultat'));
                    } else {
                        lStrTypeQCMGarde.push(GTraductions.getValeur('ExecutionQCM.presentationCorrige.DernierResultat'));
                    }
                    lStrTypeQCMGarde.push('</span>');
                    const lFnCreerExecutionPassee = function(aDateExec, aNote) {
                        const lResult = ['<div> - ', GDate.FormatDate(aDateExec, '%JJJ %JJ %MMM')];
                        if (!!aNote) {
                            lResult.push(' : ' + aNote.toString());
                        }
                        lResult.push('</div>');
                        return lResult.join('');
                    };
                    const lDateExecCopieCachee = this.executionQCM.dateExecCopieCachee;
                    const lDateExecCopieVisible = this.executionQCM.dateExecCopieVisible;
                    lHtml.push('<div style="background-color: #D7EAF0; padding: 1rem 0.5rem; margin-bottom: 2rem;">');
                    lHtml.push('<div>', GTraductions.getValeur('ExecutionQCM.presentationCorrige.QCMDejaRealise', [lStrTypeQCMGarde.join('')]), '</div>');
                    if (!!lDateExecCopieCachee) {
                        lHtml.push(lFnCreerExecutionPassee(lDateExecCopieCachee, this.executionQCM.noteCopieCachee));
                    }
                    if (!!lDateExecCopieVisible) {
                        lHtml.push(lFnCreerExecutionPassee(lDateExecCopieVisible, this.executionQCM.noteCopieVisible));
                    }
                    lHtml.push('</div>');
                }
                lHtml.push('<h1 style="text-align:center;font-size:25px;width:90%;border-bottom:' + this.couleurThemeQCM + ' 1px solid;margin:0 auto 25px;">');
                if (this._estUnIDevoir(this.executionQCM)) {
                    lHtml.push(GTraductions.getValeur('ExecutionQCM.presentationCorrige.CorrigeIdevoirExecute'));
                } else {
                    lHtml.push(GTraductions.getValeur('ExecutionQCM.presentationCorrige.CorrigeQCMExecute'));
                }
                lHtml.push('</h1>');
                const lNoteObtenue = [];
