                if (!lEstAffichageCopieCachee) {
                    if (this.executionQCM.estLieADevoir || (this.executionQCM.estUnTAF && !!this.executionQCM.afficherResultatNote)) {
                        lNoteObtenue.push('<div style="margin-bottom: 0.5em;">', GTraductions.getValeur('ExecutionQCM.presentationCorrige.noteObtenue', [this.executionQCM.noteQCM ? this.executionQCM.noteQCM.toString() : '', this.executionQCM.nombreDePoints]), '</div>');
                    }
                }
                if (!lEstAffichageCopieCachee) {
                    if (this.executionQCM.estLieAEvaluation || (this.executionQCM.estUnTAF && !!this.executionQCM.afficherResultatNiveauMaitrise)) {
                        if (!!this.executionQCM.listeCompetences && this.executionQCM.listeCompetences.GetNbrElements() > 0) {
                            let lBgColorLigne;
                            lCartoucheCompetences.push('<div style="margin-bottom: 0.5em;">', '<div style="border: solid 1px #DDD; max-height: 200px; font-size: 0.7em; overflow: auto;" id="', this.idCartoucheCompetences, '">');
                            this.executionQCM.listeCompetences.parcourir(function(D, aIndexCpt) {
                                let lPastilleNiveauAcqui;
                                if (!!D.niveauAcqui) {
                                    lPastilleNiveauAcqui = EGenreNiveauDAcquisition.getImage(D.niveauAcqui);
                                }
                                lBgColorLigne = (aIndexCpt % 2 === 0 ? '#F8F8F8' : '#FFF');
                                lCartoucheCompetences.push('<div style="padding: 0.2em 0; background-color: ', lBgColorLigne, ';">', '<span class="InlineBlock AlignementHaut AlignementMilieu" style="width: 50px;">', (lPastilleNiveauAcqui || ''), '</span>', '<span class="InlineBlock AlignementHaut" style="width: calc(100% - 150px);">', D.GetLibelle(), '</span>', '<span class="InlineBlock AlignementHaut" style="width: 100px;">', (D.strPrefixes || ''), '</span>', '</div>');
                            });
                            lCartoucheCompetences.push('  </div>', '</div>');
                        }
                    }
                }
                let lNbQuestionsTotal = this.nbQuestions || (!!this.executionQCM.QCM ? this.executionQCM.QCM.nbQuestionsTotal : 0);
                if (!lNbQuestionsTotal) {
                    lNbQuestionsTotal = this.executionQCM.nbQuestRepondues;
                }
                lReponsesDonnees.push('<div>', GTraductions.getValeur('ExecutionQCM.presentationCorrige.reponsesDonnees', [this.executionQCM.nbQuestRepondues, lNbQuestionsTotal, this.executionQCM.nbQuestBonnes]), '</div>');
                lHtml.push(this.composeLigneInfo({
                    icon: this._getIconeTypeExecutionQCM(this.executionQCM),
                    classIcon: 'alignementTop',
                    label: lNoteObtenue.join('') + lCartoucheCompetences.join('') + lReponsesDonnees.join('')
                }));
                let lTrad = '';
                let lIcone = '';
