                lHtml.push('<h1 id="', this.idWrapperTitre, this.indiceQuestion, '" style="font-size:25px;width:90%;border-bottom:' + this.couleurThemeQCM + ' 1px solid;margin:auto;font-style:italic;text-align:right;">' + GTraductions.getValeur('ExecutionQCM.TitreRessenti') + '</h1>');
