                lHtml.push('<div class="Texte24 InlineBlock AlignementMilieuVertical" style="height:100%;">', GTraductions.getValeur('ExecutionQCM.phraseRessenti'), '</div>');
                lHtml.push('<span class="AvecMain InlineBlock AlignementMilieuVertical" id="', this.idRessenti, '_0" style="width:200px;text-align:center;color:', GCouleur.grisClair, ';">', GTraductions.getValeur('ExecutionQCM.valeurRessenti')[3], '</span>');
                lHtml.push('<span class="AvecMain InlineBlock AlignementMilieuVertical" id="', this.idRessenti, '_1" style="width:200px;text-align:center;color:', GCouleur.grisClair, ';">', GTraductions.getValeur('ExecutionQCM.valeurRessenti')[1], '</span>');
