                            const lStrJours = (lNbJours > 1 ? GTraductions.getValeur('TAFEtContenu.jours') : GTraductions.getValeur('TAFEtContenu.jour')).toLowerCase();
                            T.push('<div class=" GrandEspaceGauche">');
                            T.push('<ul style="padding: 0px; margin: 0px;"><li style="list-style-position: inside; padding: 0px 0px 5px 0px;">');
                            T.push('<span class="EspaceGauche">' + GTraductions.getValeur('TAFEtContenu.donneLe') + GDate.FormatDate(lDonneeLeCourant, ' %JJ/%MM') + '</span>');
                            T.push('<span>' + ' [' + lNbJours + ' ' + lStrJours + ']</span>');
                            T.push('</li></ul>');
