            const lPadding = 'padding:1px ' + (this.params.grilleInverse ? (lEcart ? '1px ' : '0 ') : '1px ') + (!this.params.grilleInverse ? (lEcart ? '1px ' : '0 ') : '1px ') + '1px;';
