        function _evenementEditionActu(aGenreBouton, aParam) {
            const lEstCtxCreation = (aGenreBouton === 1) && aParam && (aParam.eltCree !== null) && (aParam.eltCree !== undefined);
            if (lEstCtxCreation) {
                const lEstUneCreationDepuisUnModele = (this.filtreModeItem === TypeItemEnum.IE_Modele_Info || this.filtreModeItem === TypeItemEnum.IE_Modele_Sondage) && (aParam.donnee && !aParam.donnee.estModele);
                if (this.filtreModeItem === TypeItemEnum.IE_Reception || lEstUneCreationDepuisUnModele) {
                    const lTypeItem = aParam.donnee && aParam.donnee.publie === false ? TypeItemEnum.IE_Brouillon : TypeItemEnum.IE_Diffusion_Tout;
                    let lItemASelectionnerApresSaisie = this.getItemDeType(lTypeItem);
                    this.setCtxSelection({
                        niveauEcran: 0,
                        dataEcran: lItemASelectionnerApresSaisie
                    });
                    this.modeAuteur = this.avecAuteur;
                    this.modeAff = this.genresAffichages.saisie;
                    this.filtreModeItem = lTypeItem;
                }
            }
            if (this.diffusionResultatsSondageEnCours) {
                this.diffusionResultatsSondageEnCours = false;
                if (aGenreBouton !== 1) {
                    const lListePiecesJointes = this.moteurCP.getListePiecesJointesDActualite(aParam.donnee);
                    if (!!lListePiecesJointes) {
                        lListePiecesJointes.parcourir(function(D) {
                            D.SetEtat(EGenreEtat.Suppression);
                        });
                    }
                    new ObjetRequeteSaisieFichierResultatsSondage(this).lancerRequete({
                        listePJASupprimer: lListePiecesJointes
                    });
                } else {
                    _reponseSaisie.call(this);
                }
            } else {
                if (aGenreBouton === 1) {
                    if (aParam && (aParam.eltCree !== null) && (aParam.eltCree !== undefined)) {
                        this.contexte.selectionCouranteModeDiffusion = aParam.eltCree;
                    }
                    _reponseSaisie.call(this);
                }
            }
        }

        function declencherSaisie() {
            const lObjetSaisie = {
                listeActualite: this.listeActualites,
                validationDirecte: false,
                saisieActualite: this.modeAuteur
            };
            new ObjetRequeteSaisieActualites(this, _reponseSaisie.bind(this)).lancerRequete(lObjetSaisie);
        }

        function _reponseSaisie(aXml, aJSONReponse, aJSONRapportSaisie) {
            if (this.modeAuteur) {
                if (aJSONRapportSaisie !== null && aJSONRapportSaisie !== undefined && aJSONRapportSaisie.infoSondCree !== null && aJSONRapportSaisie.infoSondCree !== undefined) {
                    this.contexte.selectionCouranteModeDiffusion = aJSONRapportSaisie.infoSondCree;
                }
                this.RecupererDonnees();
            }
        }

        function _donneesFenetreEditionDiscussion(aInfoSond) {
            const lDonnees = {};
            const lAuteur = aInfoSond.elmauteur;
            if (_estSurEspaceProfesseurOuPersonnel()) {
                const lListeEns = new ObjetListeElements();
                const lListePers = new ObjetListeElements();
                switch (lAuteur.GetGenre()) {
                    case EGenreRessource.Enseignant:
                        lListeEns.AddElement(lAuteur);
                        break;
                    case EGenreRessource.Personnel:
                        lListePers.AddElement(lAuteur);
                        break;
                    default:
                        break;
                }
                const lGenresRessources = [{
                    genre: EGenreRessource.Enseignant,
                    listeDestinataires: lListeEns
                }, {
                    genre: EGenreRessource.Personnel,
                    listeDestinataires: lListePers
                }];
                lDonnees.genresRessources = lGenresRessources;
            } else {
                lDonnees.genreRessource = lAuteur.GetGenre();
                const lListe = new ObjetListeElements();
                lListe.AddElement(lAuteur);
                lDonnees.ListeRessources = lListe;
                lDonnees.listeSelectionnee = lListe;
            }
            let lStrTraduc, lParamsTraduc;
            const lEstInfo = aInfoSond.estInformation;
            if (aInfoSond.GetLibelle()) {
                lStrTraduc = lEstInfo ? 'actualites.discussion.enReponseAInformation' : 'actualites.discussion.enReponseAuSondage';
                lParamsTraduc = [aInfoSond.GetLibelle(), GDate.FormatDate(aInfoSond.dateDebut, '%J/%MM/%AAAA')];
            } else {
                lStrTraduc = lEstInfo ? 'actualites.discussion.enReponseAInformationDu' : 'actualites.discussion.enReponseAuSondageDu';
                lParamsTraduc = [GDate.FormatDate(aInfoSond.dateDebut, '%J/%MM/%AAAA')];
            }
            lDonnees.message = {
                objet: GTraductions.getValeur('actualites.discussion.reponse', [aInfoSond.GetLibelle()]),
                contenu: GTraductions.getValeur(lStrTraduc, lParamsTraduc)
            };
            return lDonnees;
        }

