                            const lClass = lEstAujourdHui ? 'couleurClaireDuTheme ' : '';
                            const lLibelleJour = GDate.FormatDate(dateCourante, this._formatDateGrille);
                            const lNbJour = GDate.getNbrJoursDepuisPremiereLundi(dateCourante);
                            const ajouterCreation = this.eventCreation && !lEstGrisePassee && !lEstUnJourFerie ? ' onclick="' + this.eventCreation.interfacePere + '.' + this.eventCreation.callback + '(' + lNbJour + ')"' : '';
                            let lCouleurFond = 'background-color : white;';
                            if (lEstUnJourFerie) {
                                lCouleurFond = 'background-color : ' + GCouleur.themeNeutre.legere + ';';
                            } else if (lEstGrisePassee) {
                                lCouleurFond = 'background-color : ' + GCouleur.themeNeutre.light + ';';
                            }
