            ConstruireStructureAffichageAutre() {
                const H = [];
                const lAcces = GEtatUtilisateur.getAcces();
                if (!lAcces.autorise) {
                    return this.composeMessage(GTraductions.getValeur('EDT.EDTNonConsultable'));
                } else if (!lAcces.autoriseSurDate) {
                    return this.composeMessage(GTraductions.getValeur('EDT.EDTconsultableDuAu', [GDate.FormatDate(lAcces.dateDebut, '%JJ/%MM/%AA'), GDate.FormatDate(lAcces.dateFin, '%JJ/%MM/%AA')]));
                }
                const LCadre = 0;
                const LStyle = this.couleurFond ? GStyle.composeCouleurFond(this.couleurFond) : '';
                H.push('<div>');
                H.push('<table class="AlignementHaut Espace"');
                H.push(' style="' + LStyle + 'width:100%; height:100%;" border="0" cellpadding="0" cellspacing="' + LCadre + '">');
                H.push('<tr>');
                H.push('<td class="AlignementHaut" id="' + this.GetInstance(this.IdentCalendrier).GetNom() + '" style="width: 100%; height:10px">', GHtml.composeBlanc(), '</td>');
                if (this.avecListeEleves) {
                    H.push('<td id="', _getIdConteneurListeEleves.call(this), '" class="AlignementHaut EspaceGauche" rowspan="3"', !GEtatUtilisateur.getAfficherListeElevesEDT() ? ' style="display:none"' : '', '>', '<div id="', this.GetInstance(this.identListeEleves).GetNom(), '" style="width:240px;', GStyle.composeHeightCalc(5), '">', '</div></td>');
                }
                H.push('</tr>');
                if (this.GetInstance(this.identTabs)) {
                    H.push('<tr id="', this.idTabsOnglet + '"', (GEtatUtilisateur.getOnglet().typePlanningEDT === TypeHoraireGrillePlanning.ongletParJour ? '' : ' style="display:none;"'), '>', '<td id="', this.GetInstance(this.identTabs).GetNom(), '" class="AlignementHaut PetitEspaceHaut" style="height:10px;', GStyle.composeCouleurBordure(GCouleur.bordure, 1, EGenreBordure.bas), '">', '</td></tr>');
                }
                H.push('<tr>');
                H.push('<td class="AlignementHaut" id="' + this.GetInstance(this.IdentGrille).GetNom() + '" style="height: 100%">', GHtml.composeBlanc(), '</td>');
                H.push('</tr>');
                H.push('</table>');
                H.push('</div>');
                return H.join('');
            }
            initialiserTripleCombo(aInstance) {
                if (this.avecComboSalle) {
                    aInstance.SetParametres([EGenreRessource.Salle]);
                } else if (this.avecComboEleve) {
                    aInstance.SetParametres([EGenreRessource.Classe, EGenreRessource.Eleve]);
                } else if (this.avecComboProfesseur) {
                    aInstance.SetParametres([EGenreRessource.Enseignant]);
                } else if (this.avecComboPersonnel) {
                    aInstance.SetParametres([EGenreRessource.Personnel]);
                } else if (this.avecComboMateriel) {
                    aInstance.SetParametres([EGenreRessource.Materiel]);
                } else {
                    aInstance.SetParametres([EGenreRessource.Classe], true);
                }
            }
