                    const lGenreBouton = this.ordreBoutons[I];
                    const lVisible = this._estBoutonVisible(this.genre, lGenreBouton);
                    const lActif = aActif === undefined ? this._estBoutonActif(lGenreBouton) : aActif;
                    const lLibelle = this._getLibelleBouton(lGenreBouton, lActif);
                    const lHint = this._getHintBouton(lGenreBouton, lActif);
                    GHtml.setDisplay(this._getIdBouton(lGenreBouton), lVisible);
                    this.GetInstance(this.identBoutons[lGenreBouton]).SetActif(lActif);
                    this.GetInstance(this.identBoutons[lGenreBouton]).SetLibelle(lLibelle);
                    this.GetInstance(this.identBoutons[lGenreBouton]).setHint(lHint);
